import java.util.ArrayList;
import java.util.List;
import java.util.function.Predicate;
import java.util.function.Supplier;

public class Main {
    public static void main(String[] args) {
        Predicate<String> pendek = s -> s.length() <= 4;
        Predicate<String> awalanA = s -> s.startsWith("a");

        System.out.println(pendek.test("kopi"));
        System.out.println(pendek.and(awalanA).test("kopi"));
        System.out.println(pendek.or(awalanA).test("alpukat"));
        System.out.println(pendek.negate().test("teh"));

        Supplier<String> menuHariIni = () -> "Nasi goreng";
        System.out.println(menuHariIni.get());

        Supplier<List<String>> daftarBaru = () -> new ArrayList<>();
        List<String> belanja = daftarBaru.get();
        belanja.add("telur");
        System.out.println(belanja);
    }
}

