import java.util.Arrays;
import java.util.List;
import java.util.function.Predicate;
import java.util.function.Supplier;

public class Main {
    public static void main(String[] args) {
        List<Integer> nilai = Arrays.asList(45, 80, 72, 90, 55);
        Supplier<String> judul = () -> "Laporan Nilai";
        Predicate<Integer> lulus = x -> x >= 70;
        Predicate<Integer> tinggi = x -> x >= 85;
        System.out.println(judul.get());
        for (int n : nilai) {
            if (lulus.and(tinggi.negate()).test(n)) {
                System.out.println(n);
            }
        }
    }
}

